mapper.select:
SELECT ipr.target_category, ipr.target_type, ipr.plan_id, ipr.target_id, ipr.standard_id, is2.NAME AS standard_name, ipr.item_id, isi.alias AS item_name, isi.NAME AS itemContent, ir.item_name AS defaultResult, GROUP_CONCAT( ir2.item_name SEPARATOR ',' ) AS resultNames FROM inspect_plan_relation ipr LEFT JOIN inspect_standard is2 ON ( is2.id = ipr.standard_id ) LEFT JOIN inspect_standard_item isi ON ( isi.id = ipr.item_id ) LEFT JOIN inspect_result ir ON ( ir.id = isi.result_id AND isi.result_item_value = ir.item_value ) LEFT JOIN inspect_result ir2 ON ( ir2.id = isi.result_id ) where ipr.is_raw_item = 1 and ipr.plan_id = #{plainId}
and ipr.target_id = #{targetId}
GROUP BY ipr.standard_id, is2.NAME, ipr.item_id, ir.NAME, isi.NAME

SELECT ipr.target_category, ipr.target_type, ipr.plan_id, ipr.target_id, ipr.standard_id, is2.NAME AS standard_name, ipr.item_id, iit.alias AS item_name, iit.NAME AS itemContent, ir.item_name AS defaultResult, GROUP_CONCAT( ir2.item_name SEPARATOR ',' ) AS resultNames FROM inspect_plan_relation ipr LEFT JOIN inspect_standard is2 ON ( is2.id = ipr.standard_id ) LEFT JOIN inspect_item_template iit ON ( iit.id = ipr.item_id ) LEFT JOIN inspect_result ir ON ( ir.id = iit.result_id AND iit.result_item_value = ir.item_value ) LEFT JOIN inspect_result ir2 ON ( ir2.id = iit.result_id ) where ipr.is_raw_item = 1 and ipr.plan_id = #{plainId}
and ipr.target_id = #{targetId}
GROUP BY ipr.standard_id, is2.NAME, ipr.item_id, ir.NAME, iit.NAME

select plan_id,target_category,target_id from inspect_plan_relation
where plan_id = #{plainId}

    and target_category = #{targetCategory}

group by target_id
ORDER BY
FIELD(target_category, ${orderBy})

select b.id ,b.name,b.`describe`,b.code,b.enable from inspect_standard b


        b.id in

            #{standardId}

SELECT 0 AS 'isRawItem', id, alias, refer_type AS 'referType', `name`, content, result_item_value AS 'resultItemValue', image_result AS 'imageResult', item_tag AS 'itemTag', remark_result AS remarkResult, result_id AS 'resultId' FROM inspect_item_template
id in
#{itemId}

SELECT 1 AS 'isRawItem', id, alias, refer_type AS 'referType', `name`, content, result_item_value AS 'resultItemValue', image_result AS 'imageResult', item_tag AS 'itemTag', remark_result AS 'remarkResult', result_id AS 'resultId' FROM inspect_standard_item
id in
#{itemId}

SELECT 1 AS is_raw_item, id, alias, refer_type AS refer_type, name, content, result_item_value AS result_item_value, image_result AS image_result, item_tag AS item_tag, remark_result AS remark_result, result_id AS result_id FROM inspect_standard_item
AND id IN
#{itemId}
